"""``workpeg ui serve --fake-cloud``: where the dev server listens, whom
it answers, the hosts line and the certificate.

A dev install's page is served from the developer's own computer at
``https://<namespace>.dev.workpeg.com``, and the browser hands that page the
signed-in person's whole Workpeg session. :mod:`workpeg.ui.devmode` decides
what may start and :mod:`workpeg.ui.devsite` what is served; this module
puts it on the network, and only as far as this computer.

PORT 443, OR NOTHING

The API admits a dev page's origin only with no port in it, so the server
listens on 443 or does not start. There is no search for a free port and no
8443: a busy 443 is one line saying so, and nothing else is tried.

WHERE IT LISTENS

- macOS lets a program without root use 443 only on every interface, so it
  binds ``0.0.0.0:443``. That is safe only because of the peer check.
- Linux and Windows bind ``127.0.0.1:443``. Linux keeps 443 for root, and
  a refusal names the two narrow ways to allow it, never sudo.

THE PEER CHECK, BEFORE TLS

The server is :class:`workpeg.ui.serve.LoopbackTLSServer`. Its listening
socket is never wrapped: each connection is accepted raw, and one whose peer
is not this computer's loopback address is closed with nothing written, no
ServerHello and no certificate. Only then is it wrapped and its handshake
run, in its own thread. The check is held as the server class had it when
this module was loaded, and a class whose check has been replaced since is
not bound at all, on any OS. That catches a check replaced while workpeg
runs, nothing more: a copy of serve.py that has lost it in its source
passes, and only the DOOR test that connects from another address sees
it. A kernel never takes a loopback source address in
from a network interface, so no other computer passes. It does not stop the
developer, who can change their own copy of the SDK; the API enforces what
the page may do. It stops another computer being answered by accident.

THE HOSTS LINE

The name is mapped to ``127.0.0.1`` alone, in a line marked as workpeg's.
A marked line for the name with any other address, such as the ``::1`` line
an older ``--fake-cloud`` wrote, is taken out, so no other program on this
computer listening on ``[::1]:443`` is handed the session. A line workpeg
did not write that maps the name anywhere else is the developer's, so it is
not touched: the server refuses and names it. The file is read again after
pruning, and a line for another address still there, marked or not,
refuses too.

THE CERTIFICATE

mkcert's, or none. The edge sends HSTS for the dev host, so a browser that
has seen it lets nobody click through a certificate warning, and a
self-signed pair is useless. A cached pair is reused only when mkcert made
it (signed by a CA, not by itself) and it has more than seven days left;
any other is made again.
"""
from __future__ import annotations

import errno
import os
import shutil
import ssl
import subprocess
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path
from urllib.parse import quote

from workpeg import terminal
from workpeg.terminal import shown as _shown
from workpeg.ui import fake_cloud, serve
from workpeg.ui.devmode import DEV_PORT, _q

#: The address of this computer the hosts line names, and Linux and Windows
#: listen on.
LOOPBACK = "127.0.0.1"

#: Where macOS listens: the only address it lets a program without root
#: use 443 on.
EVERY_INTERFACE = "0.0.0.0"

#: The peer check as the server class has it when this module is loaded,
#: so that a check replaced at runtime is seen before anything is bound.
_PEER_CHECK = serve.LoopbackTLSServer.verify_request

#: A cached certificate with this long left, or less, is made again.
RENEW_WITHIN = timedelta(days=7)

#: Windows' code for a port in use, where ``errno`` may not carry it.
_WSAEADDRINUSE = 10048

MAC_LISTENING = (
    "Listening on port 443 on every interface, because macOS lets a program "
    "use 443 without root only that way. Only this computer is answered: "
    "every other address is closed before TLS. If macOS asks whether python "
    "may accept incoming connections, choose Deny; this computer's browser "
    "is not affected.")
LOOPBACK_LISTENING = "Listening on 127.0.0.1:443, this computer only."

#: The dashboard page where an owner or admin may press Install for
#: testing. Optional: a dev page has the access of the account signed in,
#: and the API makes its test tables in each business on first use.
INSTALL_PAGE = "https://developers.workpeg.com/dev-install/"
INSTALL_WHO = (
    "(optional: the API makes this peg's test tables in each business on "
    "first use)")

#: The red banner, in the owner's words, printed before where it listens.
DEVELOPMENT_ONLY = terminal.DEV_PAGE

IN_USE = (
    "Something on this computer already uses port 443, often an earlier "
    "workpeg server. Stop it and run this again.")
WINDOWS_IN_USE = IN_USE + " `netstat -ano | findstr :443` names it."
LINUX_LOW_PORT = (
    "Linux keeps port 443 for root. Either give one Python the right to use "
    "low ports: `sudo setcap cap_net_bind_service=+ep {python}`, which lasts "
    "until that file changes; or, until reboot, `sudo sysctl -w "
    "net.ipv4.ip_unprivileged_port_start=443`, which lets every program of "
    "every user on this computer use ports 443 to 1023. Do not run workpeg "
    "with sudo.")
LINUX_LINKED = (
    " {python} is a link, and setcap would mark the file it points to for "
    "everyone who runs it: make a venv with `python3 -m venv --copies` and "
    "run workpeg from that one.")
LOW_PORT = (
    "This computer would not let workpeg use port 443. Stop whatever holds "
    "it and run this again. Do not run workpeg with sudo.")
NO_PEER_CHECK = (
    "A dev page is answered only behind the check that closes every other "
    "computer's connection before TLS, and something in this Python has "
    "replaced that check since workpeg loaded. Run it again without "
    "whatever replaced it.")
MKCERT_MISSING = (
    "A dev page needs mkcert, so that your browser trusts this computer's "
    "certificate for https://{domain} with no warning to click through. "
    "{install}, then run this again.")
MKCERT_INSTALL = {
    "darwin": "Install it with `brew install mkcert`",
    "linux": ("Install your distribution's mkcert package (for example "
              "`sudo apt install mkcert libnss3-tools`, `sudo dnf install "
              "mkcert nss-tools` or `sudo pacman -S mkcert`)"),
    "win32": "Install it with `choco install mkcert` or `scoop install mkcert`",
}
MKCERT_FAILED = (
    "mkcert could not make a certificate for {domain}. Run `mkcert -install` "
    "in this terminal, then run this again.")
CERT_UNLOADABLE = (
    "The certificate in {folder} will not load. Delete that folder and run "
    "this again.")
HOSTS_UNREADABLE = "{path} cannot be read, so {domain} cannot be mapped."
HOSTS_FOREIGN = (
    "{path} maps {domain} to an address in a line workpeg did not write, "
    "{line}, so your browser could take this page and your session "
    "somewhere other than this computer. Remove that line and run this "
    "again.")
HOSTS_LEFT = (
    "{path} still maps {domain} to an address other than 127.0.0.1 after "
    "workpeg took out its own lines, in {line}, so your browser could take "
    "this page and your session somewhere other than this computer. Remove "
    "that line and run this again.")


class DevServeRefused(Exception):
    """The dev page's server will not set up this computer. ``str()`` is
    the line to print."""


def _system() -> str:
    """``darwin``, ``win32`` or ``linux``: which row of the table this
    computer is. Any other unix listens as Linux does."""
    if sys.platform == "darwin":
        return "darwin"
    if sys.platform.startswith("win"):
        return "win32"
    return "linux"


# ---------------------------------------------------------------- the bind

def bind_host() -> str:
    """The one address the dev server listens on, for this OS."""
    return EVERY_INTERFACE if _system() == "darwin" else LOOPBACK


def listening_words() -> str:
    """What the developer is told about where it listens."""
    return MAC_LISTENING if _system() == "darwin" else LOOPBACK_LISTENING


def install_link(namespace: str) -> str:
    """The dashboard's Install for testing page for *namespace*, the
    namespace URL-encoded whole, so nothing in it ends the path."""
    return INSTALL_PAGE + quote(namespace, safe="")


def _low_port_words() -> str:
    if not sys.platform.startswith("linux"):
        return LOW_PORT
    python = _shown(sys.executable)
    words = LINUX_LOW_PORT.format(python=python)
    if os.path.islink(sys.executable):
        words += LINUX_LINKED.format(python=python)
    return words


def _in_use(error: OSError) -> bool:
    return (error.errno == errno.EADDRINUSE
            or getattr(error, "winerror", None) == _WSAEADDRINUSE)


def bind(handler, tls: ssl.SSLContext) -> serve.LoopbackTLSServer:
    """The dev server, bound to port 443 on this OS's address, behind the
    peer check. Raises :class:`workpeg.ui.serve.ServeError` with the words
    for a port it cannot have; it never tries another."""
    server_cls = serve.LoopbackTLSServer
    if server_cls.verify_request is not _PEER_CHECK:
        raise serve.ServeError(NO_PEER_CHECK)
    try:
        return server_cls((bind_host(), DEV_PORT), handler, tls)
    except PermissionError as error:
        raise serve.ServeError(_low_port_words()) from error
    except OSError as error:
        if _in_use(error):
            raise serve.ServeError(
                WINDOWS_IN_USE if _system() == "win32" else IN_USE
            ) from error
        raise


# ----------------------------------------------------------- the hosts line

def _maps(line: str, domain: str) -> "str | None":
    """The address *line* maps *domain* to, or None."""
    fields = line.split("#")[0].split()
    if len(fields) >= 2 and domain in (name.lower() for name in fields[1:]):
        return fields[0]
    return None


def _read_hosts(path: str, domain: str) -> str:
    try:
        return Path(path).read_text()
    except OSError:
        raise DevServeRefused(HOSTS_UNREADABLE.format(
            path=_q(path), domain=domain)) from None


def _elsewhere(content: str, domain: str) -> list:
    """The lines of *content* that map *domain* to anything but
    127.0.0.1."""
    found = []
    for line in content.splitlines():
        address = _maps(line, domain)
        if address is not None and address != LOOPBACK:
            found.append(line)
    return found


def ensure_hosts_line(domain: str) -> bool:
    """Map *domain* to 127.0.0.1 alone, in a marked line. True when the
    line was added, False when it was there. Refuses when a line workpeg
    did not write maps the name anywhere else, or when one for another
    address is still there after workpeg took out its own."""
    fake_cloud._require_valid_domain(domain)
    path = fake_cloud.hosts_path_for_os()
    elsewhere = _elsewhere(_read_hosts(path, domain), domain)
    for line in elsewhere:
        if fake_cloud._HOSTS_MARKER not in line:
            raise DevServeRefused(HOSTS_FOREIGN.format(
                path=_q(path), domain=domain, line=_q(line.strip())))
    try:
        if elsewhere:
            fake_cloud.remove_hosts_entry(domain, path, keep=(LOOPBACK,))
            left = _elsewhere(_read_hosts(path, domain), domain)
            if left:
                raise DevServeRefused(HOSTS_LEFT.format(
                    path=_q(path), domain=domain, line=_q(left[0].strip())))
        return fake_cloud.ensure_hosts_entry(domain, path)
    except fake_cloud.FakeCloudError as error:
        raise DevServeRefused(str(error)) from None


# ---------------------------------------------------------- the certificate

def _mkcert(domain: str) -> str:
    """mkcert's path, or a refusal saying how to install it here."""
    found = shutil.which("mkcert")
    if found is None:
        raise DevServeRefused(MKCERT_MISSING.format(
            domain=domain, install=MKCERT_INSTALL[_system()]))
    return found


def _tlv(data: bytes, at: int) -> "tuple[int, int, int]":
    """``(tag, start, end)`` of the DER value at *at*."""
    if at + 2 > len(data):
        raise ValueError("truncated")
    tag, length = data[at], data[at + 1]
    at += 2
    if length & 0x80:
        size = length & 0x7F
        if not 1 <= size <= 4 or at + size > len(data):
            raise ValueError("bad length")
        length = int.from_bytes(data[at:at + size], "big")
        at += size
    if at + length > len(data):
        raise ValueError("truncated")
    return tag, at, at + length


def _children(data: bytes, start: int, end: int) -> list:
    found, at = [], start
    while at < end:
        tag, inner, after = _tlv(data, at)
        found.append((tag, inner, after))
        at = after
    return found


def _time(tag: int, text: str) -> datetime:
    if tag == 0x17:                                   # UTCTime
        when = datetime.strptime(text, "%y%m%d%H%M%SZ")
    elif tag == 0x18:                                 # GeneralizedTime
        when = datetime.strptime(text, "%Y%m%d%H%M%SZ")
    else:
        raise ValueError("not a time")
    return when.replace(tzinfo=timezone.utc)


def _certificate(path: Path) -> "tuple[bytes, bytes, datetime]":
    """``(issuer, subject, not after)`` of the certificate in *path*, read
    from its DER by hand. Raises ValueError for anything it cannot read."""
    der = ssl.PEM_cert_to_DER_cert(path.read_text(encoding="ascii"))
    _tag, start, end = _tlv(der, 0)
    tbs_tag, tbs_start, tbs_end = _children(der, start, end)[0]
    if tbs_tag != 0x30:
        raise ValueError("no certificate body")
    fields = _children(der, tbs_start, tbs_end)
    if fields and fields[0][0] == 0xA0:               # the version
        fields = fields[1:]
    _serial, _algorithm, issuer, validity, subject = fields[:5]
    times = _children(der, validity[1], validity[2])
    if len(times) != 2:
        raise ValueError("no validity")
    tag, inner, after = times[1]
    not_after = _time(tag, der[inner:after].decode("ascii"))
    return (der[issuer[1]:issuer[2]], der[subject[1]:subject[2]], not_after)


def _reusable(cert: Path, key: Path, kind: Path) -> bool:
    """Whether a cached pair is one mkcert made, with more than
    :data:`RENEW_WITHIN` left."""
    try:
        if not key.is_file() or kind.read_text().strip() != "mkcert":
            return False
        issuer, subject, not_after = _certificate(cert)
    except (OSError, ValueError, IndexError, UnicodeError):
        return False
    if issuer == subject:                    # signed by itself
        return False
    return not_after - datetime.now(timezone.utc) > RENEW_WITHIN


def ensure_certificate(domain: str, mkcert: str) -> "tuple[str, str]":
    """``(cert, key)`` for *domain*, made by *mkcert* unless a pair it made
    is cached with time to spare."""
    fake_cloud._require_valid_domain(domain)
    folder = Path(fake_cloud._CERT_ROOT) / domain
    cert, key, kind = folder / "cert.pem", folder / "key.pem", folder / "kind"
    if _reusable(cert, key, kind):
        return str(cert), str(key)
    try:
        folder.mkdir(parents=True, exist_ok=True)
        subprocess.run([mkcert, "-install"], check=True, capture_output=True)
        subprocess.run(
            [mkcert, "-cert-file", str(cert), "-key-file", str(key), domain],
            check=True, capture_output=True)
        fake_cloud._lock_down_key(key)
        kind.write_text("mkcert")
    except (OSError, subprocess.CalledProcessError):
        raise DevServeRefused(MKCERT_FAILED.format(domain=domain)) from None
    return str(cert), str(key)


# ------------------------------------------------------------------ running

def prepare(plan) -> ssl.SSLContext:
    """Set this computer up for *plan* (a :class:`workpeg.ui.devmode.DevPlan`)
    and return the server's TLS. mkcert is looked for first, so a computer
    without it is refused before the hosts file is touched."""
    mkcert = _mkcert(plan.domain)
    added = ensure_hosts_line(plan.domain)
    cert, key = ensure_certificate(plan.domain, mkcert)
    try:
        tls = serve._tls_context(cert, key)
    except (OSError, ssl.SSLError):
        raise DevServeRefused(CERT_UNLOADABLE.format(
            folder=_q(Path(cert).parent))) from None
    note = "added" if added else "already present"
    print(f"\n  Hosts       →  {LOOPBACK} {_shown(plan.domain)} ({note})")
    print("  TLS         →  mkcert (browser-trusted)")
    return tls


def run(plan, directory: str, tls: ssl.SSLContext) -> None:
    """Serve what the build in *directory* wrote, at ``https://<domain>``,
    until Ctrl+C. Every save builds as a release does."""
    from workpeg.ui.devsite import DevSite
    from workpeg.ui.watcher import FileWatcher

    folder = str(Path(directory).resolve())
    # Read off the build that has just run, before anything is served.
    site = DevSite(folder, plan.entry)
    handler, broadcast = serve._make_reload_handler(
        folder, site, domain=plan.domain)
    server = bind(handler, tls)
    try:
        FileWatcher(
            str(plan.watch),
            serve._make_watcher_callback(
                str(plan.watch), folder, broadcast, rebuild=site.rebuild),
        ).start()
        print(f"\n  Dev install →  https://{_shown(plan.domain)}/")
        print(f"  Install     →  {install_link(plan.namespace)}")
        print(f"                 {INSTALL_WHO}")
        print(f"  Watching    →  {_shown(str(plan.watch))}", flush=True)
        # Before where it listens, on stderr so that it survives `| tee`.
        terminal.warn(DEVELOPMENT_ONLY, sys.stderr)
        print(f"\n  Listening   →  {listening_words()}")
        print("  Stop        →  Ctrl+C\n", flush=True)
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        print("\nStopped.")
